"""Professional Marketplace dashboard and mobile-first view.

This is an independent UI shell over the existing Marketplace state/actions.
It does not touch Core or automate platform accounts.
"""
from __future__ import annotations
import argparse, html, json
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from urllib.parse import urlparse
from marketplace_mvp import _now, load_state, save_state, DATA_FILE
from marketplace.pipeline import ingest_mostaql_opportunity, offer_quality
from marketplace.opportunity_queue import queue_metrics, rank_queue
from marketplace.revenue import analytics
from marketplace.review import metrics
from marketplace.followup import due_followups
from marketplace.server import handle_action, build_offer, log_activity
HOST="127.0.0.1"; PORT=8766

def e(v): return html.escape(str(v or ""), quote=True)
def link(v):
 p=urlparse(str(v or "").strip()); return e(v) if p.scheme in {"http","https"} and p.netloc else ""
def status(x): return str(x.get("lifecycle",x.get("status","DRAFT"))).upper()
def badge(s): return f'<span class="badge b-{e(s.lower().replace("_","-"))}">{e(s)}</span>'
CSS="""*{box-sizing:border-box}body{margin:0;background:#f4f6f9;color:#101828;font:14px Arial,Tahoma,sans-serif}.app{display:grid;grid-template-columns:230px 1fr;min-height:100vh}.side{background:#0b1220;color:#fff;padding:22px 14px;position:sticky;top:0;height:100vh}.brand{font-size:19px;font-weight:800;padding:8px 10px 24px}.brand small{display:block;color:#94a3b8;font-size:10px;margin-top:4px}.nav a{display:block;color:#cbd5e1;text-decoration:none;padding:11px;border-radius:9px;margin:3px 0}.nav a:hover,.nav a.active{background:#1e293b;color:#fff}.note{position:absolute;bottom:16px;left:16px;right:16px;color:#94a3b8;font-size:11px;line-height:1.7}.main{padding:26px;max-width:1500px;width:100%;margin:auto}.top{display:flex;justify-content:space-between;align-items:center;gap:14px;margin-bottom:18px}.eyebrow{font-size:10px;font-weight:800;color:#667085}.top h1{margin:5px 0;font-size:27px}.muted{color:#667085}.search,input,textarea{border:1px solid #d0d5dd;border-radius:9px;padding:10px;font:inherit}.search{width:290px}.btn{border:1px solid #d0d5dd;background:#fff;border-radius:9px;padding:9px 12px;cursor:pointer;text-decoration:none;font-weight:700;font-size:12px}.primary,.dark{background:#111827;color:#fff;border-color:#111827}.kpis{display:grid;grid-template-columns:repeat(6,1fr);gap:9px;margin-bottom:14px}.kpi,.panel,.card,.mini{background:#fff;border:1px solid #e4e7ec;border-radius:13px}.kpi{padding:14px}.kpi span{font-size:10px;color:#667085}.kpi b{display:block;font-size:25px;margin-top:6px}.layout{display:grid;grid-template-columns:minmax(0,1.7fr) minmax(280px,.75fr);gap:13px}.panel{padding:16px;margin-bottom:13px}.head{display:flex;justify-content:space-between;align-items:center;margin-bottom:11px}.head h2{font-size:17px;margin:0}.cards{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:9px}.card,.mini{padding:13px}.cardtop{display:flex;justify-content:space-between;gap:8px}.card h3{margin:3px 0;font-size:15px}.badge{padding:5px 8px;border-radius:99px;background:#f2f4f7;font-size:10px;font-weight:800;white-space:nowrap}.b-approved,.b-won{background:#ecfdf3;color:#067647}.b-submitted,.b-offer-ready,.b-ready-for-review{background:#eff8ff;color:#175cd3}.b-rejected,.b-lost,.b-failed{background:#fef3f2;color:#b42318}.desc{color:#475467;line-height:1.7}.metrics{display:grid;grid-template-columns:repeat(4,1fr);gap:6px;margin:10px 0}.metrics div{background:#f8fafc;border-radius:8px;padding:7px}.metrics span{display:block;color:#667085;font-size:9px}.metrics b{font-size:13px}.next{background:#f8fafc;padding:8px;border-radius:8px}.next span{display:block;color:#667085;font-size:9px;margin-bottom:3px}.actions{display:flex;flex-wrap:wrap;gap:6px;margin-top:8px}details{border-top:1px solid #eef2f6;margin-top:9px;padding-top:8px}summary{font-weight:700;cursor:pointer;font-size:12px}input,textarea{width:100%;margin-top:4px}textarea{min-height:90px;line-height:1.7}label{display:block;font-size:11px;font-weight:700;margin-top:7px}.notice{background:#f8fafc;border:1px solid #e4e7ec;border-radius:8px;padding:9px;font-size:11px;color:#667085}.activity{list-style:none;padding:0}.activity li{padding:8px 0;border-bottom:1px solid #eef2f6;font-size:12px}.activity span{color:#98a2b3;margin-left:7px}.empty{text-align:center;background:#f8fafc;padding:20px;color:#667085;border-radius:9px}.progress{height:8px;background:#eef2f6;border-radius:99px;overflow:hidden}.progress i{display:block;height:100%;background:#111827}.bottom{display:none}@media(max-width:1100px){.app{grid-template-columns:70px 1fr}.brand{font-size:0;text-align:center}.brand small,.nav span,.note{display:none}.kpis{grid-template-columns:repeat(3,1fr)}.layout{grid-template-columns:1fr}}@media(max-width:760px){.app{display:block}.side{height:auto;display:flex;align-items:center;justify-content:space-between;position:sticky;z-index:10;top:0;padding:7px}.brand{font-size:14px;padding:6px}.nav{display:flex;overflow:auto;gap:3px}.nav a{white-space:nowrap;padding:8px}.main{padding:12px 12px 65px}.top{display:block}.tools{margin-top:9px}.search{width:100%}.kpis{grid-template-columns:1fr 1fr}.cards{grid-template-columns:1fr}.metrics{grid-template-columns:1fr 1fr}.bottom{display:flex;position:fixed;bottom:0;left:0;right:0;background:#fff;border-top:1px solid #e4e7ec;justify-content:space-around;padding:9px;z-index:20}.bottom a{font-size:11px;font-weight:700;text-decoration:none}}"""
JS="""async function post(u,p){let r=await fetch(u,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(p)}),d=await r.json();alert(d.message||d.error||'تم');if(d.ok)location.reload()}async function act(id,a,e={}){return post('/api/action',Object.assign({id,action:a},e))}async function copyOffer(id){let x=document.getElementById(id);await navigator.clipboard.writeText(x.value);alert('تم نسخ العرض')}async function winOpportunity(id){let v=prompt('قيمة الصفقة بالجنيه المصري:');if(v!==null)await act(id,'won',{amount_egp:+v})}async function addOpportunity(e){e.preventDefault();await post('/api/opportunity',{title:oppTitle.value,description:oppDescription.value,source_url:oppUrl.value,price_usd:+oppPrice.value,days:+oppDays.value,notes:oppNotes.value});return false}function filterCards(){let q=search.value.toLowerCase().trim();document.querySelectorAll('.searchable').forEach(x=>x.style.display=x.dataset.search.toLowerCase().includes(q)?'block':'none')}"""
def button(t,c,p=False): return f'<button class="btn {"primary" if p else ""}" onclick="{c}">{t}</button>'
def opportunity(x):
 i=e(x.get("id"));s=status(x);price=int(x.get("suggested_price_usd",5));days=int(x.get("suggested_days",3));score=int(x.get("acquisition_score",x.get("match_score",0)));q=offer_quality(x);u=link(x.get("source_url"));a=''
 if s in {"DRAFT","OFFER_READY","REJECTED","FAILED"}:a+=button("إرسال للمراجعة",f"act('{i}','ready')")
 if s=="READY_FOR_REVIEW":a+=button("اعتماد",f"act('{i}','approve')",True)+button("رفض",f"act('{i}','reject')")
 if s=="APPROVED":a+=button("تسجيل كمُرسل",f"act('{i}','submit')",True)
 if s=="SUBMITTED":a+=button("تسجيل فوز",f"winOpportunity('{i}')",True)+button("تسجيل خسارة",f"act('{i}','lost')")+button("تمت المتابعة",f"act('{i}','follow_up')")
 return f'<article class="card searchable" data-search="{e(x.get("title"))} {e(x.get("description"))} {s}"><div class="cardtop"><div><div class="eyebrow">مستقل · فرصة</div><h3>{e(x.get("title"))}</h3></div>{badge(s)}</div><p class="desc">{e(x.get("description"))}</p><div class="metrics"><div><span>الأولوية</span><b>{score}%</b></div><div><span>السعر</span><b>${price}</b></div><div><span>المدة</span><b>{days} أيام</b></div><div><span>الجودة</span><b>{"ناجح" if q.get("passed") else "مراجعة"}</b></div></div><div class="next"><span>ماذا أفعل الآن؟</span><b>{e(x.get("next_action") or "راجع العرض ثم اعتمده")}</b></div><div class="actions">{f'<a class="btn dark" href="{u}" target="_blank">فتح المشروع على مستقل</a>' if u else ''}</div><details open><summary>العرض — مراجعة ونسخ</summary><textarea id="offer-{i}">{e(x.get("offer"))}</textarea><div class="actions">{button("نسخ العرض",f"copyOffer('offer-{i}')")}</div></details><div class="actions">{a}</div></article>'
def due(x):
 i=e(x.get("id"));u=link(x.get("source_url"));return f'<article class="mini"><div class="cardtop"><b>{e(x.get("title"))}</b>{badge(status(x))}</div><p>موعد المتابعة: <strong>{e(x.get("next_followup_at"))}</strong></p><div class="actions">{f'<a class="btn dark" href="{u}" target="_blank">فتح المشروع على مستقل</a>' if u else ''}{button("تمت المتابعة",f"act(\'{i}\',\'follow_up\')",True)}</div></article>'
def render(s,mobile=False):
 q=queue_metrics(s);r=analytics(s);d=due_followups(s,_now());o=rank_queue(s)[:20];sv=s.get("services",[]);pf=s.get("portfolio",[]);ac=s.get("activity",[])[:12];rev=metrics(s);pct=min(100,max(0,r.get("revenue_egp",0)/200))
 cards=''.join(opportunity(x) for x in o) or '<div class="empty">لا توجد فرص.</div>'; dues=''.join(due(x) for x in d) or '<div class="empty">لا توجد متابعة مستحقة الآن.</div>'
 service_html=''.join('<article class="mini"><b>'+e(x.get("title"))+'</b><p>'+e(x.get("description"))+'</p></article>' for x in sv) or '<div class="empty">لا توجد خدمات.</div>'
 activity_html=''.join('<li><span>'+e(x.get("time"))+'</span>'+e(x.get("message"))+'</li>' for x in ac) or '<li>لا يوجد نشاط.</li>'
 extra='' if mobile else f'<section class="panel"><div class="head"><h2>خدمات خمسات</h2></div><div class="cards">{service_html}</div></section><section class="panel" id="revenue"><div class="head"><h2>الإيرادات والهدف</h2><b>{r.get("revenue_egp",0):.0f} ج</b></div><div class="progress"><i style="width:{pct:.1f}%"></i></div><p class="muted">المتبقي {r.get("remaining_to_target_egp",0):.0f} ج · التحويل {r.get("conversion_pct",0):.1f}%</p></section><section class="panel"><div class="head"><h2>آخر النشاط</h2></div><ul class="activity">{activity_html}</ul></section>'
 return f'''<!doctype html><html lang="ar" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#0b1220"><title>خيرت Marketplace</title><style>{CSS}</style></head><body><div class="app"><aside class="side"><div class="brand">خيرت Marketplace<small>Control Center</small></div><nav class="nav"><a class="active" href="#overview"><span>نظرة عامة</span></a><a href="#followups"><span>المتابعات</span></a><a href="#opportunities"><span>الفرص</span></a><a href="#revenue"><span>الإيرادات</span></a></nav><div class="note">الخادم لا يسجل دخولًا أو ينشر تلقائيًا.</div></aside><main class="main"><div class="top" id="overview"><div><div class="eyebrow">KHYRAT 2030 · MARKETPLACE</div><h1>{"نسخة الموبايل" if mobile else "لوحة التحكم الاحترافية"}</h1><div class="muted">تنفيذ يومي واضح وسريع.</div></div><div class="tools"><input id="search" class="search" placeholder="ابحث..." oninput="filterCards()"><a class="btn dark" href="{'/' if mobile else '/mobile/'}">{"لوحة المكتب" if mobile else "الموبايل"}</a></div></div><div class="kpis"><div class="kpi"><span>فرص مفتوحة</span><b>{q.get('total',0)}</b></div><div class="kpi"><span>أولوية عالية</span><b>{q.get('high',0)}</b></div><div class="kpi"><span>في المراجعة</span><b>{q.get('review',0)}</b></div><div class="kpi"><span>متابعات</span><b>{len(d)}</b></div><div class="kpi"><span>الخدمات</span><b>{rev.get('services',0)}</b></div><div class="kpi"><span>المحقق</span><b>{r.get('revenue_egp',0):.0f} ج</b></div></div><div class="layout"><div><section class="panel" id="followups"><div class="head"><h2>مهام اليوم</h2><span class="badge">{len(d)} مستحقة</span></div><div class="cards">{dues}</div></section><section class="panel" id="opportunities"><div class="head"><h2>أفضل الفرص</h2></div><div class="cards">{cards}</div></section>{extra}</div>{'' if mobile else '<div><section class="panel"><div class="head"><h2>إضافة فرصة</h2></div><div class="notice">السعر بالدولار: 5$ أو مضاعفاته فقط.</div><form onsubmit="return addOpportunity(event)"><label>العنوان<input id="oppTitle" required></label><label>الوصف<textarea id="oppDescription" required></textarea></label><label>رابط المشروع<input id="oppUrl" type="url"></label><label>السعر ($)<input id="oppPrice" type="number" min="5" step="5" value="5"></label><label>المدة بالأيام<input id="oppDays" type="number" min="1" value="3"></label><label>ملاحظات<textarea id="oppNotes"></textarea></label><div class="actions"><button class="btn primary">إضافة وتحليل وتوليد العرض</button></div></form></section></div>'}</div></main></div><nav class="bottom"><a href="#followups">المتابعات</a><a href="#opportunities">الفرص</a><a href="/">المكتب</a></nav><script>{JS}</script></body></html>'''
class H(BaseHTTPRequestHandler):
 def send(self,c,b,t="text/html; charset=utf-8"):
  z=b.encode();self.send_response(c);self.send_header("Content-Type",t);self.send_header("Content-Length",str(len(z)));self.send_header("Cache-Control","no-store");self.end_headers();self.wfile.write(z)
 def body(self):return json.loads(self.rfile.read(int(self.headers.get("Content-Length","0"))) or b"{}")
 def do_GET(self):
  p=urlparse(self.path).path
  if p=="/":self.send(200,render(load_state()))
  elif p=="/mobile/":self.send(200,render(load_state(),True))
  elif p=="/api/state":self.send(200,json.dumps(load_state(),ensure_ascii=False),"application/json")
  elif p=="/api/health":self.send(200,json.dumps({"ok":True,"binding":HOST,"data_file":str(DATA_FILE)}),"application/json")
  else:self.send(404,"Not Found")
 def do_POST(self):
  try:
   p=urlparse(self.path).path;d=self.body()
   if p=="/api/action":
    ok,msg=handle_action(d);self.send(200 if ok else 400,json.dumps({"ok":ok,"message":msg,"error":None if ok else msg},ensure_ascii=False),"application/json");return
   if p=="/api/opportunity":
    title=str(d.get("title","")).strip();desc=str(d.get("description","")).strip();u=str(d.get("source_url","")).strip();price=int(d.get("price_usd",5));days=int(d.get("days",3))
    if not title or not desc:raise ValueError("العنوان والوصف مطلوبان")
    if price<5 or price%5:raise ValueError("سعر مستقل يجب أن يكون 5$ أو مضاعفاته")
    if days<1:raise ValueError("المدة يجب أن تكون يومًا واحدًا على الأقل")
    s=load_state();x=ingest_mostaql_opportunity(s,title,desc,u);x.update(suggested_price_usd=price,suggested_days=days,notes=str(d.get("notes","")).strip(),offer=build_offer(x),status="OFFER_READY",lifecycle="OFFER_READY");log_activity(s,f"إضافة فرصة يدويًا: {title}");save_state(s);self.send(200,json.dumps({"ok":True,"message":f"تمت إضافة الفرصة — المطابقة {x.get('match_score',0)}%","opportunity":x},ensure_ascii=False),"application/json");return
   self.send(404,"Not Found")
  except Exception as ex:self.send(400,json.dumps({"ok":False,"error":str(ex)},ensure_ascii=False),"application/json")
def main():
 p=argparse.ArgumentParser();p.add_argument("--port",type=int,default=PORT);a=p.parse_args();ThreadingHTTPServer((HOST,a.port),H).serve_forever()
if __name__=="__main__":main()
